//go:build s390x

package gf65536

// Vector-facility kernels (VPERM split tables) generated by go-asmgen
// (gen/galois_s390x_gen.go) into galois_s390x.s. They use only z13-baseline
// operations, so there is no feature check.
func galMulVX(dst, src []byte, tbl *[128]byte, n int)
func galMulAddVX(dst, src []byte, tbl *[128]byte, n int)

func archTiers() []tier {
	return []tier{blockTier("vx", galMulVX, galMulAddVX)}
}
